mapper.select:
SELECT po.purchase_order_id, po.order_no, bp.partner_name AS supplier_name, w.warehouse_name AS warehouse_name, po.order_date, po.expected_delivery_date, po.approval_status, po.receipt_status, po.total_amount
FROM purchase_order po
INNER JOIN business_partner bp ON bp.partner_id = po.supplier_id AND bp.company_id = po.company_id
INNER JOIN warehouse w ON w.warehouse_id = po.warehouse_id AND w.company_id = po.company_id
WHERE po.company_id = #{companyId}
AND UPPER(po.order_no) LIKE '%' || UPPER(#{orderNo}) || '%'
AND UPPER(bp.partner_name) LIKE '%' || UPPER(#{supplierName}) || '%'
AND po.order_date >= #{orderDateFrom, jdbcType=DATE}
AND po.order_date <= #{orderDateTo, jdbcType=DATE}
AND po.approval_status = #{approvalStatus}
AND po.receipt_status = #{receiptStatus}
ORDER BY po.order_date DESC, po.purchase_order_id DESC

SELECT COUNT(*)
FROM business_partner
WHERE partner_id = #{supplierId}
AND company_id = #{companyId}
AND supplier_yn = 'Y'
AND use_yn = 'Y'

SELECT COUNT(*)
FROM warehouse
WHERE warehouse_id = #{warehouseId}
AND company_id = #{companyId}
AND use_yn = 'Y'

mapper.delete:
DELETE FROM purchase_order_item
WHERE purchase_order_id = #{purchaseOrderId}
AND EXISTS
(
SELECT 1
FROM purchase_order po
WHERE po.purchase_order_id = #{purchaseOrderId}
AND po.company_id = #{companyId}
AND po.approval_status = 'DRAFT'
AND po.receipt_status = 'NOT_RECEIVED'
)
AND NOT EXISTS
(
SELECT 1
FROM purchase_order_item received_poi
WHERE received_poi.purchase_order_id = #{purchaseOrderId}
AND received_poi.received_qty > 0
)
